  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="root"></div>

    <script>
      const notificationOptions = [
        { id: "notification-email", label: "Email", value: "email" },
        { id: "notification-sms", label: "SMS", value: "sms" },
        { id: "notification-push", label: "Push Notifications", value: "push-notifications" },
      ];

      function RadioOption({ id, label, value }) {
        return `
          <div class="radio-option">
            <input id="${id}" type="radio" name="notificationPreference" value="${value}" required>
            <label for="${id}">${label}</label>
          </div>
        `;
      }

      function NotificationForm() {
        return `
          <section class="form-section" aria-labelledby="form-heading">
            <form id="notification-form">
              <p class="required-note">Fields marked with <span class="required-marker" aria-hidden="true">*</span> are required.</p>
              <div class="form-field">
                <fieldset aria-describedby="notification-help">
                  <legend id="form-heading">
                    How do you prefer to receive notifications?
                    <span class="required-marker" aria-hidden="true">*</span>
                  </legend>
                  <p id="notification-help" class="field-help">Choose one notification method.</p>
                  <div class="radio-list">
                    ${notificationOptions.map(RadioOption).join("")}
                  </div>
                </fieldset>
              </div>
              <button type="submit">Save preference</button>
              <p id="form-status" class="status-message" aria-live="polite"></p>
            </form>
          </section>
        `;
      }

      function App() {
        return `
          <div class="page-shell">
            <main id="main-content">
              <article class="card">
                <header class="card-header">
                  <h1>Notification preferences</h1>
                  <p class="intro">Tell us the best way to keep you updated with timely account and product messages.</p>
                </header>
                ${NotificationForm()}
              </article>
            </main>
          </div>
        `;
      }

      document.getElementById("root").innerHTML = App();

      document.getElementById("notification-form").addEventListener("submit", (event) => {
        event.preventDefault();

        const selected = document.querySelector('input[name="notificationPreference"]:checked');
        const status = document.getElementById("form-status");

        if (!selected) {
          document.querySelector('input[name="notificationPreference"]').focus();
          return;
        }

        const selectedLabel = document.querySelector(`label[for="${selected.id}"]`).textContent;
        status.textContent = `Preference saved: ${selectedLabel}.`;
      });
    </script>
  </body>
</html>
