const { chromium } = require('playwright');
const axeCore = require('axe-core');
const fs = require('fs');
const path = require('path');

(async () => {
  const file = path.resolve('/workspace/sandbox/skills/building-accessible-ui/radio-button-group--framework-react--style-dark/gpt-5.5__s4/index.html');
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium' });
